-- Official hardware reference (LS-12). Additive and idempotent. Generated by cli/gen_hardware_reference_migration.php from database/reference/official_hardware_sources.csv.
-- Manufacturer spec facts only: no prices, no observations, no snapshots. A candidate part enters the catalog with no market price.
-- Skipped (no monitor category yet): aoc-24g4, lg-27gp850-b, gigabyte-m27q-rev-20 (monitor rows stay in the CSV).


CREATE TABLE IF NOT EXISTS product_reference_specs (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id BIGINT UNSIGNED NOT NULL,
  spec_key VARCHAR(60) NOT NULL,
  spec_value VARCHAR(120) NOT NULL,
  unit VARCHAR(12) NULL,
  source_url VARCHAR(500) NOT NULL,
  date_checked DATE NOT NULL,
  review_status ENUM('official_checked','needs_variant_review') NOT NULL,
  review_note VARCHAR(500) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_ref_spec (product_id, spec_key),
  INDEX idx_ref_spec_key (spec_key),
  CONSTRAINT fk_ref_spec_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

SELECT c.id,b.id,'PRO B650M-A WIFI','msi-pro-b650m-a-wifi','MSI PRO B650M-A WIFI',NULL,NULL,'ซ็อกเก็ต AM5, DDR5, Micro-ATX',NULL,NULL,'AM5',NULL,'DDR5','Micro-ATX',NULL,NULL,0,1,NOW(),NOW()
FROM product_categories c JOIN brands b ON b.name='MSI' WHERE c.slug='motherboard' AND NOT EXISTS (SELECT 1 FROM products WHERE slug='msi-pro-b650m-a-wifi');

SELECT c.id,b.id,'FURY Beast DDR5-6000 32GB EXPO kit','kingston-fury-beast-ddr5-6000-32gb-expo','Kingston FURY Beast DDR5-6000 32GB EXPO kit',NULL,NULL,'DDR5, ความจุรวม 32GB',NULL,NULL,NULL,NULL,'DDR5',NULL,32,NULL,0,1,NOW(),NOW()
FROM product_categories c JOIN brands b ON b.name='Kingston' WHERE c.slug='ram' AND NOT EXISTS (SELECT 1 FROM products WHERE slug='kingston-fury-beast-ddr5-6000-32gb-expo');

